import { Component, computed, effect, input, model, OnInit, output, signal } from '@angular/core';
import { ApIconComponent } from '../ap-icon/ap-icon.component';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'ap-input-box',
  imports: [CommonModule, ApIconComponent],
  templateUrl: './ap-input-box.html',
  styleUrl: './ap-input-box.css',
})
export class ApInputBox implements OnInit {
  private static readonly DEFAULT_CURRENCY_IMAGE = 'assets/images/currency/img_coin_DEMO.svg';

  label = input<string | null>(null);
  type = input<'text' | 'number' | 'email' | 'password' | 'tel' | 'url' | 'date' | 'time'>('text');
  size = input<'small' | 'medium' | 'large'>('medium');
  accentColor = input<'orange' | 'yellow' | 'slate'>('orange');
  icon = input<string | null>(null);
  placeholder = input<string | null>(null);
  value = model<string>('');
  error = input(false);
  success = input(false);
  disabled = input(false);
  required = input(true);
  max = input<string | number | null | undefined>(null);
  maxLength = input<number | null>(null);
  /** 輸入框限制只能輸入英文及數字 */
  allowedCharacterPattern = input<RegExp | null>(null);
  min = input<string | number | null | undefined>(null);
  prefix = input<string | null>(null);
  suffix = input<string | null>(null);
  currencyImage = input<string | boolean | null>(null);
  infinity = input<string | boolean | null>(null);;
  step = input<string | number | null | undefined>(null);
  allowNegative = input(false);
  blur = output<string>();
  focus = output<void>();
  onInput = output<string>();
  increase = output<string>();
  decrease = output<string>();

  readonly nativeType = computed(() => (this.type() === 'number' ? 'text' : this.type()));
  readonly nativeInputMode = computed(() => {
    if (this.type() !== 'number') return null;
    if (this.isWholeNumberInput()) return 'numeric';
    return this.allowNegative() ? 'text' : 'decimal';
  });

  readonly currentCurrencyImage = computed(() => {
    const currencyImage = this.currencyImage();
    if (currencyImage === true) return ApInputBox.DEFAULT_CURRENCY_IMAGE;
    if (!currencyImage) return null;
    return currencyImage;
  });

  readonly effectiveStep = computed(() => this.getEffectiveStep());

  ngOnInit(): void { }

  private getDecimalPlacesFromText(value: string | null): number | null {
    if (!value || !value.includes('.')) {
      return null;
    }

    return value.split('.')[1]?.length ?? 0;
  }

  private getDecimalPlaces(): number {
    // step屬性優先，如果有設定step，則使用step的decimal places
    const stepDecimalPlaces = this.getDecimalPlacesFromText(
      this.step()?.toString() ?? null,
    );
    if (stepDecimalPlaces !== null) {
      return stepDecimalPlaces;
    }


    const valueDecimalPlaces = this.getDecimalPlacesFromText(this.value());
    if (valueDecimalPlaces !== null) {
      return valueDecimalPlaces;
    }

    const placeholderDecimalPlaces = this.getDecimalPlacesFromText(
      this.placeholder(),
    );
    if (placeholderDecimalPlaces !== null) {
      return placeholderDecimalPlaces;
    }
    return 0;
  }

  private getEffectiveStep(): string {
    // 最優先使用step屬性，如果沒有設定step，則根據value或placeholder的decimal places來決定step
    // 最後如果都沒有設定，則預設為1。
    if (this.step()) {
      return this.step()?.toString() ?? '1';
    }

    const decimalPlaces = this.getDecimalPlaces();
    if (decimalPlaces > 0) {
      return (1 / 10 ** decimalPlaces).toFixed(decimalPlaces);
    }
    return '1';
  }

  private formatNumericValue(value: number): string {
    return value.toFixed(this.getDecimalPlaces());
  }

  private isWholeNumberInput(): boolean {
    return this.type() === 'number' && this.getDecimalPlaces() === 0;
  }

  /* 輸入負值 */
  private sanitizeNumericInput(value: string): string {
    if (this.type() !== 'number') return value;

    let sanitized = value.replace(
      this.isWholeNumberInput()
        ? this.allowNegative() ? /[^0-9\-]/g : /[^0-9]/g
        : this.allowNegative() ? /[^0-9.\-]/g : /[^0-9.]/g,
      '',
    );
    const isNegative = sanitized.startsWith('-');
    sanitized = sanitized.replace(/-/g, '');
    if (isNegative) sanitized = '-' + sanitized;

    const dotIndex = sanitized.indexOf('.');
    if (dotIndex !== -1) {
      const decimalPlaces = this.getDecimalPlaces();
      sanitized =
        sanitized.slice(0, dotIndex + 1) +
        sanitized.slice(dotIndex + 1).replace(/\./g, '').slice(0, decimalPlaces);
    }
    return sanitized;
  }

  /* 是否僅可輸入數字與英文  */
  private sanitizeAllowedCharacters(value: string): string {
    const pattern = this.allowedCharacterPattern();
    if (!pattern) return value;

    return Array.from(value)
      .filter((character) => {
        pattern.lastIndex = 0;
        return pattern.test(character);
      })
      .join('');
  }

  private clampToRange(value: string): string {
    if (this.type() !== 'number') return value;
    const parsed = parseFloat(value);
    if (Number.isNaN(parsed)) return value;

    const max = this.max() !== null ? parseFloat(this.max()!.toString()) : Infinity;
    const min = this.min() !== null ? parseFloat(this.min()!.toString()) : -Infinity;
    if (parsed > max) return this.formatNumericValue(max);
    if (parsed < min) return this.formatNumericValue(min);
    return value;
  }

  onInputChange(event: Event) {
    // IME 組字期間不改寫 value，避免中斷組字並影響既有內容。
    if ((event as InputEvent).isComposing) return;

    const target = event.target as HTMLInputElement;
    const sanitizedValue = this.sanitizeAllowedCharacters(this.sanitizeNumericInput(target.value));
    const clampedValue = this.clampToRange(sanitizedValue);
    if (clampedValue !== target.value) {
      target.value = clampedValue;
    }
    this.value.set(clampedValue);
    this.onInput.emit(clampedValue);
  }

  onEnterKey(event: Event) {
    if (this.type() !== 'number') return;
    const target = event.target as HTMLInputElement;
    const parsed = parseFloat(this.value());
    if (Number.isNaN(parsed)) return;

    const formattedValue = this.clampToRange(this.formatNumericValue(parsed));
    target.value = formattedValue;
    this.value.set(formattedValue);
    this.onInput.emit(formattedValue);
  }

  increment() {
    if (this.type() !== 'number') return;
    const currentValue = parseFloat(this.value()) || 0;
    const step = parseFloat(this.effectiveStep());
    const max = this.max() !== null ? parseFloat(this.max()!.toString()) : Infinity;
    const newValue = Math.min(currentValue + step, max);
    const formattedValue = this.formatNumericValue(newValue);
    this.value.set(formattedValue);
    this.increase.emit(formattedValue);
    this.onInput.emit(formattedValue);
  }

  decrement() {
    if (this.type() !== 'number') return;
    const currentValue = parseFloat(this.value()) || 0;
    const step = parseFloat(this.effectiveStep());
    const min = this.min() !== null ? parseFloat(this.min()!.toString()) : -Infinity;
    const newValue = Math.max(currentValue - step, min);
    const formattedValue = this.formatNumericValue(newValue);
    this.value.set(formattedValue);
    this.decrease.emit(formattedValue);
    this.onInput.emit(formattedValue);
  }
}
